<?php
require_once __DIR__ . '/auth.php';
$stmt = $conn->prepare('SELECT e.*, u.last_login FROM employees e LEFT JOIN users u ON u.employee_id=e.id WHERE e.id=? LIMIT 1');
$stmt->bind_param('i', $employeeId);
$stmt->execute();
$employee = $stmt->get_result()->fetch_assoc();
if (!$employee) { die('Employee profile not found.'); }
?>
